class BankAccount:
    def __init__(self, balance):
        self.balance = balance

    def deposit(self, x):
        self.balance += x

    def withdraw(self, x):
        if self.balance >= x:
            self.balance -= x
            return True
        return False

    def get_balance(self):
        return self.balance

setup:
def run_ops(obj, steps):
    out = []
    for step in steps:
        name, *args = step
        r = getattr(obj, name)(*args)
        if r is not None:
            out.append(r)
    return out
